--
-- Name: ims_action_submissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ims_action_submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id text NOT NULL,
    gstin text NOT NULL,
    period character varying(7) NOT NULL,
    chosen_action text NOT NULL,
    recommended_action text,
    submit_mode text DEFAULT 'confirm_recommendation'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reference_id text,
    transaction_id text,
    status_cd text,
    error_code text,
    error_message text,
    raw_poll jsonb,
    run_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ims_action_submissions_chosen_action_check CHECK ((chosen_action = ANY (ARRAY['accept'::text, 'reject'::text, 'hold'::text, 'pending'::text]))),
    CONSTRAINT ims_action_submissions_period_check CHECK (((period)::text ~ '^[0-9]{4}-[0-9]{2}$'::text)),
    CONSTRAINT ims_action_submissions_status_check CHECK ((status = ANY (ARRAY['claiming'::text, 'pending'::text, 'confirmed'::text, 'failed'::text, 'unclear'::text]))),
    CONSTRAINT ims_action_submissions_submit_mode_check CHECK ((submit_mode = ANY (ARRAY['confirm_recommendation'::text, 'override'::text])))
);


--
-- Name: TABLE ims_action_submissions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ims_action_submissions IS 'Idempotent IMS Accept/Reject/Hold writebacks keyed by (invoice_id, period, gstin). Non-failed rows block re-submit.';


--
-- Name: COLUMN ims_action_submissions.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ims_action_submissions.status IS 'claiming = row reserved before Sandbox save; pending = save accepted / polling; confirmed|failed|unclear = terminal.';


--
-- Name: claim_ims_action_submission(text, text, character varying, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ims_action_submission(p_invoice_id text, p_gstin text, p_period character varying, p_chosen_action text, p_recommended_action text DEFAULT NULL::text, p_submit_mode text DEFAULT 'confirm_recommendation'::text, p_run_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.ims_action_submissions
    LANGUAGE plpgsql
    AS $$
DECLARE
    claimed public.ims_action_submissions%ROWTYPE;
    g text := upper(btrim(p_gstin));
    p character varying := left(btrim(p_period), 7);
BEGIN
    -- 1) First writer wins: atomic insert, conflict does nothing.
        invoice_id,
        gstin,
        period,
        chosen_action,
        recommended_action,
        submit_mode,
        status,
        run_id
    ) VALUES (
        p_invoice_id,
        g,
        p,
        p_chosen_action,
        p_recommended_action,
        COALESCE(NULLIF(btrim(p_submit_mode), ''), 'confirm_recommendation'),
        'claiming',
        p_run_id
    )
    ON CONFLICT (invoice_id, period, gstin) DO NOTHING
    RETURNING * INTO claimed;

    IF FOUND THEN
        RETURN NEXT claimed;
        RETURN;
    END IF;

    -- 2) Only failed rows may be reclaimed for retry (still atomic).
    UPDATE public.ims_action_submissions AS s
    SET
        status = 'claiming',
        chosen_action = p_chosen_action,
        recommended_action = p_recommended_action,
        submit_mode = COALESCE(NULLIF(btrim(p_submit_mode), ''), 'confirm_recommendation'),
        run_id = COALESCE(p_run_id, s.run_id),
        reference_id = NULL,
        transaction_id = NULL,
        status_cd = NULL,
        error_code = NULL,
        error_message = NULL,
        raw_poll = NULL,
        updated_at = now()
    WHERE s.invoice_id = p_invoice_id
      AND s.period = p
      AND s.gstin = g
      AND s.status = 'failed'
    RETURNING * INTO claimed;

    IF FOUND THEN
        RETURN NEXT claimed;
    END IF;
    RETURN;
END;
$$;


--
-- Name: FUNCTION claim_ims_action_submission(p_invoice_id text, p_gstin text, p_period character varying, p_chosen_action text, p_recommended_action text, p_submit_mode text, p_run_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_ims_action_submission(p_invoice_id text, p_gstin text, p_period character varying, p_chosen_action text, p_recommended_action text, p_submit_mode text, p_run_id uuid) IS 'Atomically claim an IMS invoice for writeback. Returns the row if this caller won the claim; empty if another non-failed submission already owns the key.';


--
-- Name: delete_reconciliation_run_cascade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_reconciliation_run_cascade(p_run_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Re-point last_seen away from this run when first_seen is a different run.
  BEGIN
    UPDATE public.invoice_tracking
    SET last_seen_run_id = first_seen_run_id,
        updated_at = now()
    WHERE last_seen_run_id = p_run_id
      AND first_seen_run_id IS DISTINCT FROM p_run_id;

    DELETE FROM public.invoice_tracking
    WHERE first_seen_run_id = p_run_id
       OR last_seen_run_id = p_run_id;
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;

  BEGIN
    DELETE FROM public.rule37_actions WHERE run_id = p_run_id;
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;

  BEGIN
    DELETE FROM public.reconciliation_import_runs WHERE id = p_run_id;
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;

  -- Remaining children (results, gstr/pr records, notes, etc.) cascade.
  DELETE FROM public.reconciliation_run WHERE id = p_run_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'run not found: %', p_run_id
      USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: FUNCTION delete_reconciliation_run_cascade(p_run_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_reconciliation_run_cascade(p_run_id uuid) IS 'Deletes a reconciliation_run and non-cascading dependents (invoice_tracking, rule37_actions, import wizard) in one transaction.';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_meta jsonb := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb);
  v_role text;
  v_full_name text := NULLIF(btrim(COALESCE(v_meta->>'full_name', '')), '');
  v_firm_name text := NULLIF(btrim(COALESCE(v_meta->>'firm_name', '')), '');
  v_phone text := NULLIF(btrim(COALESCE(v_meta->>'phone', '')), '');
BEGIN
  v_role := public.user_profile_role_for_auth_user(NEW.id, NEW.email, v_meta);

  VALUES (
    NEW.id,
    NEW.email,
    v_full_name,
    v_firm_name,
    v_phone,
    v_role
  )
  ON CONFLICT (id) DO UPDATE SET
    full_name = COALESCE(v_full_name, user_profiles.full_name),
    firm_name = COALESCE(v_firm_name, user_profiles.firm_name),
    phone = COALESCE(v_phone, user_profiles.phone);

  RETURN NEW;
END;
$$;


--
-- Name: increment_invoice_number_seq(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_invoice_number_seq(p_profile_id uuid) RETURNS TABLE(prefix text, seq bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
            BEGIN
                RETURN QUERY
                UPDATE billing_company_profiles
                SET invoice_number_next_seq = invoice_number_next_seq + 1,
                    updated_at = now()
                WHERE id = p_profile_id
                RETURNING invoice_number_prefix AS prefix, (invoice_number_next_seq - 1) AS seq;
            END;
            $$;


--
-- Name: is_firm_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_firm_member(owner_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.team_members
        WHERE firm_owner_id = owner_id
          AND member_user_id = auth.uid()
          AND is_active = TRUE
    )
    OR auth.uid() = owner_id;
$$;


--
-- Name: prevent_staff_modifying_finalized_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_staff_modifying_finalized_run() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    caller_role TEXT;
BEGIN
    -- Get the role of the calling user within the run's firm
    SELECT COALESCE(up.role, 'staff')
    INTO caller_role
    FROM public.user_profiles up
    WHERE up.id = auth.uid();

    -- If run is already finalized and caller is staff, block modification
    IF OLD.finalized_at IS NOT NULL AND caller_role = 'staff' THEN
        RAISE EXCEPTION 'Staff users cannot modify finalized reconciliation runs.';
    END IF;

    -- If caller is staff, prevent them from setting finalized_at
    IF caller_role = 'staff' AND NEW.finalized_at IS DISTINCT FROM OLD.finalized_at THEN
        RAISE EXCEPTION 'Only admin users can finalize or un-finalize reconciliation runs.';
    END IF;

    RETURN NEW;
END;
$$;


