--
-- Name: user_profile_role_for_auth_user(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_profile_role_for_auth_user(p_user_id uuid, p_email text, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF NULLIF(btrim(p_meta->>'invited_by'), '') IS NOT NULL
     OR NULLIF(btrim(p_meta->>'invite_token'), '') IS NOT NULL
     OR NULLIF(btrim(p_meta->>'invited_via'), '') IS NOT NULL
  THEN
    RETURN 'staff';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.team_members tm
    WHERE tm.member_user_id = p_user_id
       OR (
         p_email IS NOT NULL
         AND lower(btrim(tm.invited_email)) = lower(btrim(p_email))
       )
  ) THEN
    RETURN 'staff';
  END IF;

  RETURN 'admin';
END;
$$;


--
-- Name: user_profiles_resolve_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_profiles_resolve_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_canonical text;
BEGIN
  v_canonical := public.user_profile_role_for_auth_user(
    NEW.id,
    NEW.email,
    '{}'::jsonb
  );

  IF TG_OP = 'INSERT' THEN
    NEW.role := v_canonical;
  ELSIF NEW.role IS NULL
        OR btrim(NEW.role) = ''
        OR lower(btrim(NEW.role)) NOT IN ('admin', 'staff') THEN
    NEW.role := v_canonical;
  END IF;

  RETURN NEW;
END;
$$;


