--
-- Name: audit_logs Admin can view audit logs; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admin can view audit logs" ON public.audit_logs FOR SELECT TO authenticated USING (((firm_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM public.user_profiles
